import{_ as d,C as i,o as c,c as l,a6 as s,E as o,j as t,a as n}from"./chunks/framework.Dzb0khVl.js";const f=JSON.parse('{"title":"DOM-Based Vulnerabilities","description":"Sources, sinks, web messages, JSON.parse, open redirects, cookie manipulation, and DOM clobbering.","frontmatter":{"title":"DOM-Based Vulnerabilities","description":"Sources, sinks, web messages, JSON.parse, open redirects, cookie manipulation, and DOM clobbering."},"headers":[],"relativePath":"dom/index.md","filePath":"dom/index.md"}'),p={name:"dom/index.md"};function u(m,e,h,g,w,b){const a=i("LabGroup"),r=i("TopicComplete");return c(),l("div",null,[e[0]||(e[0]=s('<h1 id="dom-based-vulnerabilities-·-the-case-of-the-client-side-breakdown" tabindex="-1">DOM-Based Vulnerabilities · The Case of the Client-Side Breakdown <a class="header-anchor" href="#dom-based-vulnerabilities-·-the-case-of-the-client-side-breakdown" aria-label="Permalink to &quot;DOM-Based Vulnerabilities · The Case of the Client-Side Breakdown&quot;">​</a></h1><p class="wd-section-lede">DOM-based vulnerabilities take place entirely inside your web browser. The backend server could send a completely pristine, flawless response, but client-side JavaScript takes over, reads untrusted data from an accessible source, and pipes it straight into a dangerous execution sink.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Automated PA System.</strong> Imagine an airport information desk with an automated public address system. The central flight database only sends official gate announcements. But an intern adds a script to the desk computer: <em>&quot;Check if any visitor dropped a feedback card on the counter, and if so, read it aloud over the terminal speakers.&quot;</em> Even though the airline&#39;s central servers are airtight, anyone who places a card on the counter can commandeer the airport&#39;s loudspeakers.</p></div><h2 id="case-file-1-tracing-taint-flow-from-source-to-sink" tabindex="-1">Case File #1: Tracing Taint Flow from Source to Sink <a class="header-anchor" href="#case-file-1-tracing-taint-flow-from-source-to-sink" aria-label="Permalink to &quot;Case File #1: Tracing Taint Flow from Source to Sink&quot;">​</a></h2><p>Let&#39;s trace what happens when client-side JavaScript reads a search term from your browser&#39;s address bar.</p><div class="wd-case"><div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>You visit a store page with a query in the URL: <code>/feedback?status=thankyou</code>. The page immediately displays a friendly banner: <em>&quot;Status: thankyou&quot;</em> without reloading the page from the server.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Client Script Does Behind the Scenes</span><p>A client-side script reads the <code>status</code> parameter directly from the browser&#39;s <code>location.search</code> object and inserts it into a container element using <code>innerHTML</code>:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Static Application Script</span><span><span class="wd-code-input">Gold</span> = Untrusted Data from URL Source</span></div><span class="wd-code-dev">const status = new URLSearchParams(location.search).get(&#39;status&#39;);</span><br><span class="wd-code-dev">document.getElementById(&#39;msg&#39;).innerHTML = &#39;&lt;span&gt;Status: &lt;/span&gt;&#39; + </span><span class="wd-code-input">status</span>; </div></div><div class="wd-step wd-step--break"><span class="wd-step__tag">💥 Step 3 · Where the Logic Breaks</span><p>The developer treated <code>status</code> as harmless text, but passed it into <code>innerHTML</code> (an execution sink). When an investigator sends <code>&lt;img src=x onerror=alert(1)&gt;</code>, the browser&#39;s HTML fragment parser creates the element, fails to load the image, and immediately fires the JavaScript event handler!</p></div><div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How Developers Lock It Down</span><p>Developers avoid dangerous HTML parsing sinks when handling plain text. By using safe DOM properties like <code>element.textContent = status</code>, the browser treats all characters strictly as visual text without ever compiling HTML tags or event listeners.</p></div></div><h3 id="visual-comparison-text-assignment-vs-html-fragment-parsing" tabindex="-1">Visual Comparison: Text Assignment vs. HTML Fragment Parsing <a class="header-anchor" href="#visual-comparison-text-assignment-vs-html-fragment-parsing" aria-label="Permalink to &quot;Visual Comparison: Text Assignment vs. HTML Fragment Parsing&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The developer expected the URL parameter would only contain simple status words to quickly update the screen on the client without waiting for a server round-trip.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>Because the script concatenated untrusted URL data into <code>innerHTML</code>, the browser interpreted the input as active HTML markup, executing client-side scripts inside the user&#39;s session.</p></div></div><hr><h2 id="the-taint-flow-pipeline-sources-amp-sinks" tabindex="-1">The Taint-Flow Pipeline: Sources &amp; Sinks <a class="header-anchor" href="#the-taint-flow-pipeline-sources-amp-sinks" aria-label="Permalink to &quot;The Taint-Flow Pipeline: Sources &amp;amp; Sinks&quot;">​</a></h2><p>DOM security comes down to mapping the path between where untrusted data enters the browser (<strong>Sources</strong>) and where it gets interpreted or executed (<strong>Sinks</strong>):</p><div class="wd-flow"><div class="wd-flow__node wd-flow__node--danger"><strong>1. Taint Source</strong> Data enters via <code>location.search</code>, <code>location.hash</code>, or <code>postMessage</code>. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>2. Client Logic</strong> JavaScript reads, extracts, decodes, or concatenates the tainted string. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>3. Execution Sink</strong> Data lands in <code>innerHTML</code>, <code>location.href</code>, or <code>eval</code>. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>4. Impact</strong> Browser renders markup, navigates to a new origin, or executes script. </div></div><h3 id="common-sources-and-sinks" tabindex="-1">Common Sources and Sinks <a class="header-anchor" href="#common-sources-and-sinks" aria-label="Permalink to &quot;Common Sources and Sinks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Source (Where Untrusted Data Enters)</th><th>Sink (Where Data Becomes Code)</th><th>Resulting Vulnerability</th></tr></thead><tbody><tr><td><code>location.search</code>, <code>location.hash</code></td><td><code>innerHTML</code>, <code>document.write</code></td><td>DOM Cross-Site Scripting (XSS)</td></tr><tr><td><code>location.href</code>, <code>document.referrer</code></td><td><code>location = ...</code>, <code>location.assign()</code></td><td>DOM Open Redirection / <code>javascript:</code> execution</td></tr><tr><td><code>window.name</code>, <code>postMessage</code></td><td><code>eval()</code>, <code>Function()</code>, <code>setTimeout(str)</code></td><td>Arbitrary Client-Side Code Execution</td></tr><tr><td><code>location.search</code></td><td><code>document.cookie</code></td><td>DOM Cookie Manipulation / Session Poisoning</td></tr><tr><td>HTML elements with <code>id</code>/<code>name</code></td><td>Global JS object lookups (<code>window.foo</code>)</td><td>DOM Clobbering</td></tr></tbody></table><details class="details custom-block"><summary>🔬 Under the Hood: Why innerHTML Differs from document.write</summary><p>When you assign a string to <code>element.innerHTML</code>, the browser&#39;s fragment parser treats any <code>&lt;script&gt;</code> elements inside as &quot;already evaluated&quot;, so they will not execute. However, event handlers on other elements (such as <code>&lt;img src=x onerror=...&gt;</code>) are evaluated as soon as the element is added to the DOM tree and encounters an error.</p><p>In contrast, <code>document.write()</code> injects raw characters into the live document parser while the page is rendering, allowing synchronous <code>&lt;script&gt;</code> tags to run directly.</p></details><hr><h2 id="web-messaging-the-cross-origin-channel" tabindex="-1">Web Messaging: The Cross-Origin Channel <a class="header-anchor" href="#web-messaging-the-cross-origin-channel" aria-label="Permalink to &quot;Web Messaging: The Cross-Origin Channel&quot;">​</a></h2><p>The <code>window.postMessage()</code> API allows browser windows from different origins to send text messages to each other. Because any website can post a message to an embedded iframe or opened popup, the receiver must verify two crucial details:</p><ol><li><strong>Origin Verification:</strong> Does <code>event.origin</code> exactly match a trusted domain?</li><li><strong>Data Structure Validation:</strong> Are the message properties safe before passing them to sinks?</li></ol><p>If an event listener blindly accepts messages without origin checks and writes <code>event.data</code> into an execution sink, any rogue webpage that frames the target can compromise it.</p>',20)),o(a,{ids:"dom-lab-dom-xss-using-web-messages, dom-lab-dom-xss-using-web-messages-and-a-javascript-url, dom-lab-dom-xss-using-web-messages-and-json-parse"}),e[1]||(e[1]=s('<details class="details custom-block"><summary>🔬 Under the Hood: JSON.parse is a Syntax Checker, Not a Sanitizer</summary><p>Developers sometimes believe that running <code>JSON.parse(event.data)</code> sanitizes input. It does not! <code>JSON.parse</code> only checks whether the incoming string is well-formed JSON syntax. If the parsed object contains <code>{&quot;type&quot;:&quot;redirect&quot;,&quot;url&quot;:&quot;javascript:alert(1)&quot;}</code>, the JSON parser succeeds completely, but assigning that <code>url</code> property to an iframe <code>src</code> or <code>window.location</code> executes code immediately.</p></details><hr><h2 id="dom-open-redirection" tabindex="-1">DOM Open Redirection <a class="header-anchor" href="#dom-open-redirection" aria-label="Permalink to &quot;DOM Open Redirection&quot;">​</a></h2><p>When client-side scripts read a redirect destination from the URL (such as <code>?next=...</code>) and assign it directly to <code>location.href</code>, <code>location.replace()</code>, or an anchor tag&#39;s <code>href</code>, attackers can redirect the user to a malicious external origin or supply a <code>javascript:</code> pseudoprotocol URI.</p><p>Beyond phishing, open redirects in the DOM are powerful primitives for bypassing OAuth redirect allow-lists and SSRF filters.</p>',5)),o(a,{ids:"dom-lab-dom-open-redirection"}),e[2]||(e[2]=t("hr",null,null,-1)),e[3]||(e[3]=t("h2",{id:"client-side-cookie-manipulation",tabindex:"-1"},[n("Client-Side Cookie Manipulation "),t("a",{class:"header-anchor",href:"#client-side-cookie-manipulation","aria-label":'Permalink to "Client-Side Cookie Manipulation"'},"​")],-1)),e[4]||(e[4]=t("p",null,[n("If a script takes data from "),t("code",null,"location.search"),n(" and writes it into "),t("code",null,"document.cookie"),n(" (e.g. storing a preferred theme or currency), an attacker can supply values containing semicolons to set arbitrary cookies on the victim's domain.")],-1)),e[5]||(e[5]=t("p",null,"If those cookies are later reflected into the page markup by server-side code or client-side sinks, cookie manipulation escalates into stored DOM XSS.",-1)),o(a,{ids:"dom-lab-dom-cookie-manipulation"}),e[6]||(e[6]=s('<hr><h2 id="dom-clobbering-the-namespace-hijack" tabindex="-1">DOM Clobbering: The Namespace Hijack <a class="header-anchor" href="#dom-clobbering-the-namespace-hijack" aria-label="Permalink to &quot;DOM Clobbering: The Namespace Hijack&quot;">​</a></h2><p>Browsers have a legacy feature: HTML elements with an <code>id</code> or <code>name</code> attribute automatically become properties on the global <code>window</code> object and on parent <code>&lt;form&gt;</code> elements.</p><p>If client-side JavaScript references a global variable like <code>window.config</code> before it is declared, an attacker who can inject sanitized HTML (like a comment or avatar bio) can inject <code>&lt;a id=&quot;config&quot; href=&quot;javascript:alert(1)&quot;&gt;</code>. The injected HTML &quot;clobbers&quot; the expected JavaScript object, causing the script to read attacker-controlled properties!</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Vulnerable Client Script</span><span><span class="wd-code-input">Gold</span> = Clobbered Global Property</span></div><span class="wd-code-dev">const avatar = </span><span class="wd-code-input">window.userAvatar</span><span class="wd-code-dev"> || { url: &#39;/default.png&#39; };</span></div>',5)),o(a,{ids:"dom-lab-dom-xss-exploiting-dom-clobbering, dom-lab-dom-clobbering-attributes-to-bypass-html-filters"}),e[7]||(e[7]=s('<details class="details custom-block"><summary>⚙️ Engine Variations: How Browsers Name HTML Elements</summary><ul><li><code>window.elementId</code> resolves to the DOM node with that <code>id</code>.</li><li>Form elements expose child inputs by name: <code>form.action</code> resolves to an <code>&lt;input name=&quot;action&quot;&gt;</code> instead of the form&#39;s real submission URL!</li><li>If multiple elements share the same <code>name</code>, the browser groups them into an <code>HTMLCollection</code>. Calling <code>.toString()</code> on an <code>HTMLCollection</code> returns <code>[object HTMLCollection]</code>, which can bypass naive type checks.</li></ul></details><div class="wd-callout wd-callout--warn"><p><strong>🛡️ The Detective&#39;s Defense Blueprint.</strong> Never pass untrusted strings to fragment parsers (<code>innerHTML</code>, <code>outerHTML</code>, <code>document.write</code>); prefer safe setters like <code>textContent</code>. When handling URLs, parse them with the native <code>URL</code> constructor and verify that the protocol is strictly <code>https:</code>. On <code>postMessage</code> listeners, always validate <code>event.origin</code> against an exact allow-list. Prevent DOM clobbering by avoiding bare global lookups and using explicit <code>let</code>/<code>const</code> scoping.</p></div>',2)),o(r,{"topic-id":"dom-based-vulnerabilities",label:"Mark DOM vulnerabilities complete"})])}const k=d(p,[["render",u]]);export{f as __pageData,k as default};
